import java.util.Scanner;

public class Solution {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();

        int reversed = 0;
        int original = n;

        while (n > 0) {
            reversed = reversed * 10 + n % 10;
            n = n / 10;
        }

        System.out.println(original + reversed);
    }
}
